(function(){"use strict";function d(){try{var a=window.Territorio&&window.Territorio.datos&&window.Territorio.datos.historiaPesca;if(a)return a}catch{}return u}var i=function(a){return document.getElementById(a)};function c(a){return typeof escapeHtml=="function"?escapeHtml(a):String(a??"").replace(/[&<>"']/g,function(e){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[e]})}function y(a){return'<span class="chip su-3b6a3a" data-pez="'+c(a)+'" title="Toca para cargarla en la bit\xE1cora">\u{1F3A3} '+c(a)+"</span>"}function m(a){!a||!a.querySelectorAll||a.querySelectorAll("[data-pez]").forEach(function(e){e.onclick=function(){try{s("hoy")}catch{}setTimeout(function(){var o=i("fishLogSpecies");if(o){o.value=e.getAttribute("data-pez");try{o.focus(),o.scrollIntoView({behavior:"smooth",block:"center"})}catch{}}},60)}})}var u={intro:"La pesca de Penco \u2014<b>orilla, roquer\xEDo y golfo</b>\u2014 del <b>mar cret\xE1cico</b> a la <b>caleta artesanal de hoy</b>, en <b>10 periodos</b>. La historia completa vive aqu\xED; toca una especie para cargarla en tu bit\xE1cora.",eras:[{t:"\u{1FAA8} Tiempo profundo: basamento de Gondwana",cuando:"Paleozoico (~300 Ma) \xB7 z\xF3calo de la bah\xEDa",d:"Antes de ser bah\xEDa, Penco era <b>fondo y borde de Gondwana</b>: filitas y granitoides que hoy forman los <b>roquer\xEDos de Playa Negra, La Cata y Tumbes</b>. Sin mar interior todav\xEDa, pero ya est\xE1 el piso rocoso donde despu\xE9s se afirmar\xE1n <b>corrales de piedra, varaderos y caletas</b>.",sp:["Robalo","Lapa"]},{t:"\u{1F995} Mar de Quiriquina: el golfo originario",cuando:"Cret\xE1cico Superior \xB7 Maastrichtiano (72\u201366 Ma)",d:"Hace 70 millones de a\xF1os <b>todo esto era mar profundo</b> (Formaci\xF3n Quiriquina: La Cata, Quiriquina). Nadaban el plesiosaurio <b>Aristonectes quiriquinensis (9 m)</b>, <b>mosasaurios</b>, tortugas <b>Osteopygis y Euclastes</b> y el ave <b>Neogaeornis wetzeli</b>, con <b>amonites gigantes y Neilo pencana \u2014que lleva el nombre de Penco\u2014</b>. El Golfo de Arauco de hoy es el nieto peque\xF1o de ese mar.",sp:["Congrio","Corvina","Jurel"]},{t:"\u{1F33F} Selvas del carb\xF3n: delta sin bah\xEDa",cuando:"Paleoceno\u2013Eoceno (~60\u201340 Ma) \xB7 Formaci\xF3n Cosmito",d:"El mar se retira y la costa es <b>delta pantanoso</b> (arenas y carbones de <b>Cosmito</b>). R\xEDos trenzados traen nutrientes al futuro golfo: se prepara la <b>despensa</b> que alimentar\xE1 sardinas, jureles y merluzas millones de a\xF1os despu\xE9s. El <b>primer carb\xF3n de la cuenca</b> duerme aqu\xED.",sp:["Pejerrey","Robalo"]},{t:"\u2744\uFE0F Hielos y nacimiento de la bah\xEDa",cuando:"Pleistoceno \u2013 Holoceno Medio (~2 Ma \u2013 6.000 a.p.)",d:"El <b>r\xEDo Biob\xEDo desembocaba dentro de la Bah\xEDa de Concepci\xF3n</b> y la transgresi\xF3n Flandriana la inunda: se forman las <b>terrazas de 5 m y 2 m</b>, limos del Andali\xE9n y dunas. <b>Hualp\xE9n y Tumbes eran islas</b>, Quiriquina estaba antepuesta: un <b>mar interior abrigado</b>, ideal para aprender a navegar y calar redes. Nace el escenario de toda la pesca penque\xF1a.",sp:["Corvina","Lenguado","Pejerrey","Cochayuyo","Chorito"]},{t:"\u{1F6F6} Primeros navegantes: Complejo Talcahuano",cuando:"Arcaico Medio\u2013Tard\xEDo (7.000\u20132.000 a.p.) \xB7 4.580 a.p. \u2013 130 d.C.",d:"M\xE1s de <b>30 conchales</b> rodean la bah\xEDa: <b>Bellavista 1 (>3.000 m\xB2), Talcahuano 1, Playa Negra 9 aqu\xED en Penco sur</b>. Pescadores <b>sedentarios</b> con <b>pesas de red acinturadas, anzuelo, corrales de piedra</b> y navegaci\xF3n a Quiriquina. Pesca de <b>jurel, sierra, merluza y r\xF3balo</b>, caza de <b>lobo marino</b>, marisqueo de osti\xF3n, choro zapato, loco y lapa. Fechas: <b>La Trila 4.580, Bellavista 3.880\u20133.330 a.p.</b>",sp:["Jurel","Sierra","Merluza com\xFAn","Robalo","Corvina","Chorito","Lapa"]},{t:"\u{1F3FA} Pesca lafkenche: corrales y wampo",cuando:"130 d.C. \u2013 1550 \xB7 Pitr\xE9n / El Vergel",d:"Con la cer\xE1mica y la horticultura (<b>quinoa, papa, ma\xEDz</b>), la pesca se ordena por luna y estaci\xF3n: <b>corrales de piedra, anzuelo de hueso y red</b>, salida en <b>wampo</b> (canoa). <b>Corvina, robalo y pejerrey</b> en la orilla; <b>cochayuyo, luche y chorito</b> en el roquer\xEDo. Pesca de sustento con respeto estacional y trueque con el interior. Territorio <b>ayllarewe lafkenche</b> \u2014gente del mar\u2014.",sp:["Corvina","Robalo","Pejerrey","Cochayuyo","Chorito","Lapa"]},{t:"\u26F5 Colonia: puerto y despensa",cuando:"1550\u20131800 \xB7 Concepci\xF3n en Penco + traslado 1751",d:"Fundaci\xF3n de <b>Concepci\xF3n en Penco (1550)</b>: la bah\xEDa se vuelve <b>puerto y despensa</b>. Pesca de orilla y bote peque\xF1o para consumo local, pescado seco por trigo y papas con el interior. Aparece la <b>fiesta patronal</b> como marca pesquera. El <b>terremoto-maremoto de 1751</b> y el traslado al Valle de la Mocha vac\xEDan Penco por ~90 a\xF1os: la pesca vuelve a ser solo de las <b>51 familias</b> que resisten.",sp:["Corvina","Congrio","Sierra","Pejerrey","Jaiba mora"]},{t:"\u26CF\uFE0F Siglo XIX: carb\xF3n, cobre y ballena",cuando:"1800\u20131900 \xB7 Minas 1843\u20131958 + ferrocarril 1889/1914",d:"Minas de carb\xF3n y <b>fundici\xF3n de cobre de Lirqu\xE9n</b> traen <b>m\xE1s bocas y m\xE1s botes</b>: la pesca crece para alimentar a mineros y fundidores. En el Golfo faenan <b>balleneros</b>. Nacen las caletas como las conocemos: <b>Lirqu\xE9n (~1850, pescadores y alfareros), Penco, Talcahuano</b>, con chalupas a remo y vela, espinel y trasmallo. El riel acelera el hielo y la salida.",sp:["Sierra","Congrio","Jurel","Corvina","Lenguado","Erizo"]},{t:"\u{1F3ED} Siglo XX: puerto mayor, industria y vedas",cuando:"1900\u20132000 \xB7 Vipla, puerto Lirqu\xE9n, Sernapesca",d:"<b>Lirqu\xE9n puerto mayor</b> y la pesca industrial (jurel, merluza, sardina) cambian la escala del Golfo. La artesanal resiste con <b>bote a motor, cerco chico y buceo apnea</b> (piure, erizo, lapa). Llegan <b>vedas y tallas m\xEDnimas</b> (Sernapesca): merluza en septiembre, congrio en invierno, marea roja vigilada. En 1996 la <b>Ley de Caza protege</b> lobos y aves del borde. <b>Terremotos de 1939, 1960</b> golpean caletas y obligan a reconstruir.",sp:["Jurel","Merluza com\xFAn","Sierra","Congrio","Piure","Erizo","Chorito"]},{t:"\u2693 Hoy: caleta viva y pesca con medida",cuando:"2000 \u2013 actualidad \xB7 DP World + 27F + San Pedro 29-jun",d:"La pesca artesanal de <b>Lirqu\xE9n\u2013Penco (caletas El Refugio y La Cata)</b> es patrimonio vivo: <b>amanecer y pleamar mandan</b>, la luna ordena la marea y el pique. Cada 29 de junio la <b>Fiesta de San Pedro</b> bendice los botes. El <b>27F (2010)</b> da\xF1\xF3 caletas y borde y oblig\xF3 a reconstruir. El desaf\xEDo es pescar <b>lo justo</b>: respetar vedas y tallas, devolver hembras con huevos y cuidar el roquer\xEDo. Tu bit\xE1cora ayuda: anota marea, luna y carnada que funcion\xF3.",sp:["Corvina","Lenguado","Pejerrey","Robalo","Sierra","Jurel","Congrio","Merluza com\xFAn"]}],fuentes:"Fuentes: HISTORIA_PENCO (Quiriquina, bah\xEDa, conchales, caletas) \xB7 Bustos y Vergara 2004 (30 conchales) \xB7 Torres et al. 2007 (Playa Negra 9) \xB7 Fiesta de San Pedro 29-jun \xB7 Sernapesca vedas y tallas \xB7 SHOA mareas \xB7 saberes caleta Lirqu\xE9n \xB7 cat\xE1logo Pesca e Intermareal de esta app."};function l(){var a=i("pescaHistoriaPanel");if(a){var e=d(),o='<p class="muted su-b6db47">'+e.intro+"</p>";o+=e.eras.map(function(r,n){return'<div class="menstrual-card" style="margin-top:10px'+(n===0?";border-color:var(--gold)":"")+'"><h4>'+c(r.t)+'</h4><p class="muted su-2c4c6c">'+c(r.cuando)+'</p><p class="su-afb724">'+r.d+'</p><div class="su-c158a9">'+r.sp.map(y).join("")+"</div></div>"}).join(""),o+='<p class="muted su-a953a7">'+c(e.fuentes)+"</p>",a.innerHTML=o,m(a)}}var b="hoy";function s(a){b=a;var e={hoy:i("tabPescaHoy"),historia:i("tabPescaHistoria")};Object.keys(e).forEach(function(r){e[r]&&e[r].classList.toggle("btn-accent",r===a)});var o={hoy:i("pescaHoyPanel"),historia:i("pescaHistoriaPanel")};Object.keys(o).forEach(function(r){o[r]&&o[r].classList.toggle("hidden",r!==a)}),a==="historia"&&l()}function h(){var a=i("fishingTodayBox");if(a&&!i("pescaHoyPlus")){var e=document.createElement("div");e.id="pescaHoyPlus",e.innerHTML='<div class="dlg-actions su-8f9e27"><button type="button" id="phoyGoHist" class="btn su-337714">\u{1F4DC} Ver historia</button><button type="button" id="phoyGoForm" class="btn su-337714">\u{1F4D3} Ir a la bit\xE1cora</button></div>',a.appendChild(e);var o=i("phoyGoHist");o&&(o.onclick=function(){s("historia")});var r=i("phoyGoForm");r&&(r.onclick=function(){try{var n=i("fishLogDate");n&&n.scrollIntoView({behavior:"smooth",block:"center"})}catch{}})}}function p(){if(!i("fishingDialog")||!i("tabPescaHistoria")){window._phistRetry=(window._phistRetry||0)+1,window._phistRetry<60&&setTimeout(p,500);return}try{var a=i("btnFishing");a&&a.dataset&&a.dataset.keywords&&a.dataset.keywords.indexOf("historia")<0&&(a.dataset.keywords+=" historia pesca caleta lirqen san pedro wampo corral ballena carbon veda merluza jurel sierra congrio origen lafkenche")}catch{}var e=i("tabPescaHoy"),o=i("tabPescaHistoria");e&&!e.dataset.w&&(e.dataset.w="1",e.onclick=function(){s("hoy")}),o&&!o.dataset.w&&(o.dataset.w="1",o.onclick=function(){s("historia")});try{if(typeof renderFishingDialog=="function"&&!window._pescaWrapped){window._pescaWrapped=!0;var r=renderFishingDialog;renderFishingDialog=function(){var t=r.apply(this,arguments);try{h()}catch{}try{b==="historia"&&l()}catch{}return t}}}catch{}var n=i("btnFishing");n&&!n.dataset.phistW&&(n.dataset.phistW="1",n.addEventListener("click",function(){try{s("hoy")}catch{}}));try{l()}catch{}}window.PescaHistoria={tab:s,renderHistoria:l};try{Object.defineProperties(window.PescaHistoria,{historia:{get:d}})}catch{window.PescaHistoria.historia=u}try{document.addEventListener("territorio:listo",function(){try{l()}catch{}})}catch{}setTimeout(p,600)})();
